import { existsSync, readdirSync, statSync } from 'node:fs'
import { join } from 'node:path'
import { fileURLToPath } from 'node:url'
import { describe, expect, it } from 'vitest'
import { STORIES, TRIMZ } from '#/data/content'
import { COVER_VIDEOS } from '#/data/cover-videos'
import { ISK } from '#/data/isk'
import { TROPHIES } from '#/data/trophies'

/**
 * content.ts is hand-written and isk.ts/trophies.ts are generated by scripts/, so a renamed or missing asset
 * (or a duplicated slug) fails here instead of showing a broken image in production.
 */
const root = fileURLToPath(new URL('../../', import.meta.url))
/** Asset paths carry a `?v=` cache-busting suffix; the file on disk has none. */
const publicFile = (p: string) => `${root}public${p.split('?')[0]}`
const onDisk = (p: string) => existsSync(publicFile(p))

function dirSize(dir: string): number {
  let total = 0
  for (const entry of readdirSync(dir, { withFileTypes: true })) {
    const full = join(dir, entry.name)
    total += entry.isDirectory() ? dirSize(full) : statSync(full).size
  }
  return total
}

describe('stories', () => {
  it('has unique slugs and ids', () => {
    expect(new Set(STORIES.map((s) => s.slug)).size).toBe(STORIES.length)
    expect(new Set(STORIES.map((s) => s.id)).size).toBe(STORIES.length)
  })

  it('points every cover, tile, logo and gallery asset at a real file', () => {
    for (const s of STORIES) {
      expect(onDisk(s.cover), `${s.slug} cover ${s.cover}`).toBe(true)
      if (s.tile) expect(onDisk(s.tile), `${s.slug} tile ${s.tile}`).toBe(true)
      if (s.logo) expect(onDisk(s.logo.src), `${s.slug} logo ${s.logo.src}`).toBe(true)
      for (const show of s.trimz ?? []) {
        expect(TRIMZ.some((t) => t.slug === show), `${s.slug}: unknown trimz series ${show}`).toBe(true)
      }
    }
  })

  it('has a rating from the known set and at least one tag', () => {
    for (const s of STORIES) {
      expect(['SFW', '17+', '18+']).toContain(s.rating)
      expect(s.tags.length).toBeGreaterThan(0)
    }
  })

  it('keeps published media under a sensible per-file size and total public/ budget', () => {
    // Whop zips the whole build; one runaway asset or unchecked folder growth can push it past the 50 MB upload limit.
    for (const s of STORIES) {
      for (const p of [s.cover, s.tile, s.logo?.src].filter((v): v is string => !!v)) {
        expect(statSync(publicFile(p)).size, `${p} is too large`).toBeLessThan(2_000_000)
      }
    }
    expect(dirSize(`${root}public`)).toBeLessThan(50_000_000)
  })

  it('has matching .webm preview loops and generated isk assets on disk', () => {
    for (const [slug, mp4] of Object.entries(COVER_VIDEOS)) {
      expect(onDisk(mp4), `${slug} cover video ${mp4}`).toBe(true)
      const webm = mp4.replace(/\.mp4(?=\?|$)/, '.webm')
      expect(onDisk(webm), `${slug} cover webm ${webm}`).toBe(true)
    }
    for (const s of STORIES) {
      const isk = ISK[s.slug]
      expect(isk, `ISK entry for ${s.slug}`).toBeDefined()
      if (isk.introCard) expect(onDisk(isk.introCard), `${s.slug} introCard`).toBe(true)
      for (const c of isk.cast) {
        if (c.portrait) expect(onDisk(c.portrait), `${s.slug} cast portrait ${c.id}`).toBe(true)
        if (c.card) expect(onDisk(c.card), `${s.slug} cast card ${c.id}`).toBe(true)
      }
      for (const m of isk.gallery) {
        expect(onDisk(m.src), `${s.slug} gallery ${m.src}`).toBe(true)
        if (m.thumb) expect(onDisk(m.thumb), `${s.slug} gallery thumb ${m.thumb}`).toBe(true)
      }
    }
  })
})

describe('trimz series', () => {
  it('has unique slugs, poster files, and matching .webm preview loops', () => {
    expect(new Set(TRIMZ.map((t) => t.slug)).size).toBe(TRIMZ.length)
    for (const t of TRIMZ) {
      expect(onDisk(t.poster), `${t.slug} poster ${t.poster}`).toBe(true)
      if (t.tile) expect(onDisk(t.tile), `${t.slug} tile ${t.tile}`).toBe(true)
      if (t.video) {
        expect(onDisk(t.video), `${t.slug} video ${t.video}`).toBe(true)
        expect(onDisk(t.video.replace(/\.mp4(?=\?|$)/, '.webm')), `${t.slug} video webm`).toBe(true)
      }
    }
  })
})

describe('trophies', () => {
  it('only ships sets for stories that exist', () => {
    for (const [slug, set] of Object.entries(TROPHIES)) {
      expect(STORIES.some((s) => s.slug === slug), `trophies for unknown story ${slug}`).toBe(true)
      expect(set.slug).toBe(slug)
    }
  })

  it('has unique trophy ids inside a set', () => {
    for (const [, set] of Object.entries(TROPHIES)) {
      expect(new Set(set.trophies.map((t) => t.id)).size).toBe(set.trophies.length)
    }
  })
})

describe('storyOfVideo', () => {
  it('reads the world from the storyline or Trimz link in a description', async () => {
    const { storyFromDescription } = await import('#/data/youtube')
    expect(storyFromDescription('Play on IsekaiZero: https://www.isekaizero.ai/storylines/6aa78f6bd17fe984ab332064?utm_campaign=share')).toBe('acolytes')
    expect(storyFromDescription('Play: https://www.kagesekai.ai/storylines/6af2da17a519bbd9cf367837')).toBe('wristbound')
    expect(storyFromDescription('watch on trimz: https://trimz.tv/acolytes-maid-for-your-protection-side-b')).toBe('acolytes')
    expect(storyFromDescription('Subscribe for more')).toBeUndefined()
  })

  it('keeps a description\'s own words and the Trimz series it links to', async () => {
    const { blurbFromDescription, seriesFromDescription } = await import('#/data/youtube')
    expect(blurbFromDescription('made with suno since the OG is made on suno as well\nhttps://suno.com/song/00d4')).toBe('Made with suno since the OG is made on suno as well')
    expect(blurbFromDescription('Play on IsekaiZero: https://www.isekaizero.ai/storylines/6aa7\nWatch on Trimz: https://trimz.tv/acolytes-maid-for-your-protection')).toBeUndefined()
    expect(seriesFromDescription('watch on trimz: https://trimz.tv/acolytes-maid-for-your-protection-side-b')).toBe('acolytes-maid-for-your-protection-side-b')
    expect(seriesFromDescription('nothing here')).toBeUndefined()
  })

  it('uses the description link first, then the title', async () => {
    const { storyOfVideo } = await import('#/data/youtube')
    expect(storyOfVideo({ title: 'Random Bullshit GO!!!!', story: 'acolytes' })?.slug).toBe('acolytes')
    expect(storyOfVideo({ title: 'Acolytes: Maid for your Protection - Episode 3' })?.slug).toBe('acolytes')
    expect(storyOfVideo({ title: 'Channel update' })).toBeUndefined()
  })

  it('parses Atom entries including shorts, view counts, entities, and links', async () => {
    const { parseFeed } = await import('#/data/youtube')
    const xml = `
      <feed>
        <entry>
          <yt:videoId>abc123</yt:videoId>
          <title>Acolytes &amp; Friends&#39; Cut</title>
          <link rel="alternate" href="https://www.youtube.com/shorts/abc123"/>
          <published>2026-11-01T12:00:00+00:00</published>
          <media:group>
            <media:description>Watch the maid chaos&#10;https://trimz.tv/acolytes-maid-for-your-protection</media:description>
            <media:community><media:statistics views="420"/></media:community>
          </media:group>
        </entry>
      </feed>
    `
    const parsed = parseFeed(xml)
    expect(parsed).toHaveLength(1)
    expect(parsed[0]).toMatchObject({
      id: 'abc123',
      title: "Acolytes & Friends' Cut",
      published: '2026-11-01',
      views: 420,
      short: true,
      story: 'acolytes',
      series: 'acolytes-maid-for-your-protection',
    })
  })
})
